    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "街灯下 暮色沉 无声的屋檐"
        },
        {
          "id": "V1-02",
          "zh": "人走后 椅子空 积一层薄尘"
        },
        {
          "id": "V1-03",
          "zh": "全都 载上吧 风往远处走"
        },
        {
          "id": "V1-04",
          "zh": "看云流成河 就坐上云背"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "暮色沉 街也冷 卷帘门落下"
        },
        {
          "id": "V1-02",
          "zh": "人走散 屋也空 坐垫留个窝"
        },
        {
          "id": "V1-03",
          "zh": "全部 抱起来 风就往前走"
        },
        {
          "id": "V1-04",
          "zh": "云流成了河 风踩着水走"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "暮色 沉落 街巷的寂寞"
        },
        {
          "id": "V1-02",
          "zh": "人心 变幻 空荡的虚空"
        },
        {
          "id": "V1-03",
          "zh": "全部 载着 风它远去"
        },
        {
          "id": "V1-04",
          "zh": "乘着那流云 飘向天际"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "黄昏时城镇的寂寥"
        },
        {
          "id": "V1-02",
          "zh": "人们变幻的空虚"
        },
        {
          "id": "V1-03",
          "zh": "全都载着风儿远去"
        },
        {
          "id": "V1-04",
          "zh": "乘着流转的云"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "暮色里 街巷空寂"
        },
        {
          "id": "V1-02",
          "zh": "人世间 聚散无常"
        },
        {
          "id": "V1-03",
          "zh": "全部 载着风远去"
        },
        {
          "id": "V1-04",
          "zh": "流云间 乘风而行"
        }
      ]
    },
    {
      "label": "F",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "黄昏城镇的寂寥"
        },
        {
          "id": "V1-02",
          "zh": "人心变幻的空虚"
        },
        {
          "id": "V1-03",
          "zh": "风载着一切前行"
        },
        {
          "id": "V1-04",
          "zh": "乘上流云去漂泊"
        }
      ]
    }
  ]
}

